mapper.select:
SELECT mur.id, mb.id AS msg_id, mb.module_id, mb.module_name, mb.data_id, mb.msg_flag, mb.msg_type, mb.msg_title, mb.msg_body, mb.msg_href, mb.notice_time, mb.create_time FROM msg_user_rel mur LEFT JOIN msg_base mb ON mur.msg_id = mb.id WHERE mur.user_id = #{pageDTO.userId} AND mur.del_flag = #{pageDTO.delFlag}
AND mb.msg_flag IN
#{msgFlag}
AND mur.read_flag = #{pageDTO.readFlag}
AND (mb.notice_time >= #{pageDTO.startTime} and mb.notice_time < #{pageDTO.endTime})
ORDER BY mb.create_time DESC

SELECT mur.user_id, COUNT(1) AS un_read_count FROM msg_user_rel mur WHERE mur.read_flag = #{readFlag} AND mur.del_flag = #{delFlag} AND mur.user_id IN
#{userId}
GROUP BY mur.user_id
